"""Build dependency-free HTML examples. Run: python3 tools/build.py"""
from pathlib import Path
import json,hashlib
ROOT=Path(__file__).resolve().parent.parent
CSS='''*{box-sizing:border-box}body{margin:0;background:#f6f5f0;color:#24382e;font:15px/1.6 system-ui,-apple-system,"Segoe UI",sans-serif}button,select,input{font:inherit}button,select{min-height:44px;border:1px solid #bfcac1;border-radius:6px;background:white;color:inherit;padding:8px 14px}button{cursor:pointer}a{color:#285c4c}button:focus-visible,select:focus-visible,a:focus-visible,summary:focus-visible{outline:3px solid #b97937;outline-offset:3px}header{background:#203e34;color:#fff;padding:24px max(24px,calc((100vw - 1120px)/2));display:flex;justify-content:space-between;gap:16px;align-items:center}.brand{font-weight:750;letter-spacing:.04em}.pill{font-size:12px;padding:5px 10px;border:1px solid #7c9488;border-radius:20px}main{max-width:1168px;margin:auto;padding:32px 24px}h1{font-size:clamp(26px,4vw,38px);line-height:1.3;margin:0 0 12px;letter-spacing:-.04em}h2{font-size:19px;margin:0 0 18px}h3{font-size:16px;margin:0 0 8px}p{margin:8px 0}.intro{color:#5b6c61;max-width:800px}.overline{color:#826b4f;font-size:12px;letter-spacing:.1em;margin-bottom:12px}.toolbar{display:flex;flex-wrap:wrap;align-items:end;gap:16px;margin:26px 0}.toolbar label{display:grid;gap:6px;font-size:13px}.toolbar select{min-width:150px}.toolbar button{margin-left:auto}.stats{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:16px;margin-bottom:24px}.stat,.panel{background:white;border:1px solid #dce3d8;border-radius:8px;padding:22px;min-width:0}.stat span{color:#5c6a60;font-size:13px}.stat strong{display:block;font-size:clamp(22px,3vw,30px);margin:8px 0;letter-spacing:-.04em;font-variant-numeric:tabular-nums}.stat small{color:#5c6a60}.stat:first-child{background:#e9f0e7}.grid{display:grid;grid-template-columns:1.65fr 1fr;gap:20px}.panel{margin-bottom:20px}.chart{height:260px;display:flex;align-items:stretch;gap:10px;padding-top:12px}.column{flex:1;min-width:0;display:flex;flex-direction:column;justify-content:end;align-items:center}.bars{height:220px;display:flex;gap:3px;align-items:end;width:100%;justify-content:center}.bar{width:42%;max-width:30px;background:#315f50;border-radius:3px 3px 0 0;min-height:1px}.bar.alt{background:#c68c59}.column small{font-size:11px;margin-top:7px}.legend{display:flex;gap:16px;font-size:12px;color:#5c6a60}.legend span:before{content:"";display:inline-block;width:9px;height:9px;background:#315f50;margin-right:6px}.legend span+span:before{background:#c68c59}.breakdown{margin-bottom:19px}.breakdown p{display:flex;justify-content:space-between;gap:12px}.track{height:8px;border-radius:5px;background:#edf0e9;overflow:hidden}.track i{display:block;background:#527762;height:100%}.table-wrap{overflow:auto}table{border-collapse:collapse;width:100%;font-size:14px;white-space:nowrap}th,td{padding:12px 14px;border-bottom:1px solid #e3e8e0;text-align:left}th{color:#617064;font-size:12px}td.num{text-align:right;font-variant-numeric:tabular-nums}.notice{font-size:13px;color:#5c6a60;margin:20px 0}.board{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:16px}.lane{background:#edf0e8;padding:14px;border-radius:6px}.lane h2{font-size:15px;display:flex;justify-content:space-between}.task{background:#fff;border:1px solid #d4ddce;border-radius:6px;padding:15px;margin:12px 0}.task small{color:#6f786b}.task .channel{display:inline-block;background:#eee8dd;color:#7a603f;border-radius:4px;font-size:11px;padding:2px 6px;margin-bottom:9px}.task time{display:block;font-size:12px;color:#617064;margin-top:12px}.empty{padding:22px 0;color:#6b7469}.live{font-size:13px;color:#5c6a60;margin-bottom:12px}details{border-top:1px solid #dce3d8;padding:16px 0}summary{cursor:pointer;font-weight:600}footer{max-width:1168px;margin:auto;padding:0 24px 30px;font-size:12px;color:#677369}svg{max-width:100%}@media(max-width:760px){main{padding:24px 16px}header{padding:20px 16px}.stats{grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.stat{padding:16px}.grid{grid-template-columns:1fr}.board{grid-template-columns:repeat(2,minmax(0,1fr))}.toolbar button{margin-left:0}.chart{gap:4px}.panel{padding:18px}.pill{white-space:nowrap}}@media(max-width:440px){.board{grid-template-columns:1fr}.toolbar label{flex:1}.toolbar select{min-width:0;width:100%}.stats strong{font-size:22px}}@media(prefers-reduced-motion:reduce){*{scroll-behavior:auto!important}}'''
FIN=[{'month':f'2026-{i:02}','income':round((460+((i*37)%150))*10000),'expense':round((270+((i*23)%110))*10000)} for i in range(1,13)]
SALES=[{'month':f'2026-{i:02}','channel':c,'orders':n,'revenue':n*price,'refund':round(n*price*.025)} for i in range(1,13) for c,n,price in [('온라인',80+(i*13)%55,42000),('오프라인',45+(i*7)%30,36000),('제휴',20+(i*5)%22,51000)]]
TASKS=[{'title':t,'channel':c,'stage':st,'date':d,'owner':o} for t,c,st,d,o in [
('AI 용어 카드뉴스','Instagram','기획','2026-11-10','지민'),('업무 자동화 입문','YouTube','제작','2026-11-12','서윤'),('주간 AI 소식','뉴스레터','검토','2026-11-08','민준'),('대시보드 활용법','YouTube','발행','2026-11-05','지민'),('프롬프트 체크리스트','Instagram','제작','2026-11-11','서윤'),('레퍼런스 모음','뉴스레터','발행','2026-11-03','민준'),('카메라 움직임 비교','YouTube','기획','2026-11-18','서윤'),('실무 팁 5가지','Instagram','검토','2026-11-09','지민'),('11월 제작 노트','뉴스레터','기획','2026-11-20','민준'),('컴포넌트 이름 사전','Instagram','발행','2026-11-02','지민'),('파일 정리 자동화','YouTube','검토','2026-11-07','서윤'),('월간 결산','뉴스레터','제작','2026-11-25','민준')]]
CONFIG={
'finance':{'title':'재정 관리','en':'FINANCE OVERVIEW','intro':'들어온 돈과 나간 돈을 함께 보고, 기간별 수지를 확인하세요.','note':'수지는 선택 기간의 수입 − 지출입니다. 계좌의 실제 잔액이나 세후 이익을 뜻하지 않습니다.','data':FIN},
'sales':{'title':'매출 현황','en':'SALES OVERVIEW','intro':'채널과 기간을 바꾸며 매출, 주문 수, 환불을 비교하세요.','note':'매출은 환불 전 금액, 객단가는 매출 ÷ 주문 수입니다. 세금·원가·이익은 포함하지 않습니다.','data':SALES},
'content':{'title':'콘텐츠 운영','en':'CONTENT STUDIO','intro':'기획부터 발행까지. 채널별 제작 현황과 다음 일정을 한눈에 확인하세요.','note':'일정은 2026년 11월 가상 예시입니다. 보드는 조회용이며 드래그 이동·일정 저장·게시 기능은 없습니다.','data':TASKS}}
JS='''const $=s=>document.querySelector(s);const won=n=>new Intl.NumberFormat('ko-KR').format(n)+'원';const count=n=>new Intl.NumberFormat('ko-KR').format(n);const sum=(rows,key)=>rows.reduce((a,r)=>a+r[key],0);const esc=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function stat(label,value,note){return `<div class="stat"><span>${esc(label)}</span><strong>${esc(value)}</strong><small>${esc(note)}</small></div>`}
function bars(rows,a,b){const max=Math.max(1,...rows.map(r=>Math.max(r[a],b?r[b]:0)));return `<div class="chart" role="img" aria-label="월별 비교 차트. 정확한 수치는 아래 상세 표에서 확인하세요.">${rows.map(r=>`<div class="column"><div class="bars"><div class="bar" style="height:${r[a]/max*100}%" title="${esc(r.month)} ${won(r[a])}"></div>${b?`<div class="bar alt" style="height:${r[b]/max*100}%" title="${won(r[b])}"></div>`:''}</div><small>${Number(r.month.slice(5))}월</small></div>`).join('')}</div>`}
function breakdown(rows,key,total){return rows.map(r=>`<div class="breakdown"><p><span>${esc(r.label)}</span><strong>${won(r[key])}</strong></p><div class="track"><i style="width:${total?r[key]/total*100:0}%"></i></div></div>`).join('')}
function render(){let rows=DATA;const channel=$('#channel')?.value||'전체';const period=Number($('#period')?.value||12);if(channel!=='전체')rows=rows.filter(r=>r.channel===channel);if(KIND!=='content')rows=rows.filter(r=>Number(r.month.slice(5))>12-period);
if(KIND==='finance'){const income=sum(rows,'income'),expense=sum(rows,'expense');$('#stats').innerHTML=stat('총 수입',won(income),'선택 기간 합계')+stat('총 지출',won(expense),'선택 기간 합계')+stat('기간 수지',won(income-expense),'수입 − 지출')+stat('수지 비율',(income?(income-expense)/income*100:0).toFixed(1)+'%','수지 ÷ 수입');$('#chart').innerHTML=bars(rows,'income','expense');$('#breakdown').innerHTML=breakdown([{label:'수입',v:income},{label:'지출',v:expense}],'v',Math.max(income,expense));$('#rows').innerHTML=rows.map(r=>`<tr><td>${r.month}</td><td class="num">${won(r.income)}</td><td class="num">${won(r.expense)}</td><td class="num">${won(r.income-r.expense)}</td></tr>`).join('');}
if(KIND==='sales'){const revenue=sum(rows,'revenue'),orders=sum(rows,'orders'),refund=sum(rows,'refund');$('#stats').innerHTML=stat('매출',won(revenue),'환불 전 금액')+stat('주문 수',count(orders)+'건','선택 채널 합계')+stat('객단가',won(orders?Math.round(revenue/orders):0),'매출 ÷ 주문 수')+stat('환불액',won(refund),'선택 기간 합계');const months=[...new Set(rows.map(r=>r.month))].map(month=>({month,revenue:sum(rows.filter(r=>r.month===month),'revenue')}));$('#chart').innerHTML=bars(months,'revenue');const channels=[...new Set(rows.map(r=>r.channel))].map(c=>({label:c,v:sum(rows.filter(r=>r.channel===c),'revenue')}));$('#breakdown').innerHTML=breakdown(channels,'v',revenue);$('#rows').innerHTML=rows.map(r=>`<tr><td>${r.month}</td><td>${esc(r.channel)}</td><td class="num">${count(r.orders)}</td><td class="num">${won(r.revenue)}</td><td class="num">${won(r.refund)}</td></tr>`).join('');}
if(KIND==='content'){const stages=['기획','제작','검토','발행'];$('#stats').innerHTML=stages.map(stage=>stat(stage,count(rows.filter(r=>r.stage===stage).length)+'건','선택 채널 기준')).join('');$('#board').innerHTML=stages.map(stage=>{const items=rows.filter(r=>r.stage===stage).sort((a,b)=>a.date.localeCompare(b.date));return `<section class="lane"><h2>${stage}<span>${items.length}</span></h2>${items.map(r=>`<article class="task"><span class="channel">${esc(r.channel)}</span><h3>${esc(r.title)}</h3><small>담당 ${esc(r.owner)}</small><time datetime="${r.date}">${stage==='발행'?'발행':'예정'} ${r.date}</time></article>`).join('')||'<p class="empty">해당 항목이 없어요.</p>'}</section>`}).join('');}
$('#status').textContent=(KIND==='content'?channel+' 채널':`2026년 ${13-period}–12월 · ${channel==='전체'?'전체':channel}`)+' · 가상 데이터 '+rows.length+'건';}
document.querySelectorAll('select').forEach(el=>el.addEventListener('change',render));$('#reset').addEventListener('click',()=>{document.querySelectorAll('select').forEach(el=>el.selectedIndex=0);render()});render();'''
for key,c in CONFIG.items():
 period='<label>기간<select id="period"><option value="3">최근 3개월</option><option value="6">최근 6개월</option><option value="12">전체 12개월</option></select></label>' if key!='content' else ''
 options=['온라인','오프라인','제휴'] if key=='sales' else ['YouTube','Instagram','뉴스레터']
 channel='<label>채널<select id="channel"><option>전체</option>'+''.join('<option>'+o+'</option>' for o in options)+'</select></label>' if key!='finance' else ''
 if key=='content':body='<div id="board" class="board" aria-label="콘텐츠 제작 단계"></div>'
 else:
  heads=['월','수입','지출','수지'] if key=='finance' else ['월','채널','주문 수','매출','환불액']
  body='<div class="grid"><section class="panel"><h2>월별 '+('수입과 지출' if key=='finance' else '매출 추이')+'</h2><div class="legend"><span>'+('수입</span><span>지출' if key=='finance' else '매출')+'</span></div><div id="chart"></div></section><section class="panel"><h2>'+('기간 합계 비교' if key=='finance' else '채널별 매출 구성')+'</h2><div id="breakdown"></div><p class="notice">'+c['note']+'</p></section></div><section class="panel"><h2>상세 내역</h2><div class="table-wrap" tabindex="0" role="region" aria-label="상세 데이터 표"><table><caption class="notice">필터가 적용된 가상 데이터 · 금액 단위 원</caption><thead><tr>'+''.join('<th scope="col">'+h+'</th>' for h in heads)+'</tr></thead><tbody id="rows"></tbody></table></div></section>'
 script='const KIND='+json.dumps(key)+';\n// 가상 예시 데이터입니다. 실제 데이터 연결 시 이 배열과 집계 기준을 함께 검토하세요.\nconst DATA='+json.dumps(c['data'],ensure_ascii=False)+';\n'+JS
 html='<!doctype html>\n<!-- Jane’s Picks · MIT · Copyright (c) 2026 Jane / Dante Labs -->\n<html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+c['title']+' · 제인의 픽</title><style>'+CSS+'</style></head><body><header><span class="brand">JANE’S PICKS / '+c['en']+'</span><span class="pill">가상 데이터 · v1.0.0</span></header><main><p class="overline">나의 업무에 맞게 바꾸는 대시보드</p><h1>'+c['title']+'</h1><p class="intro">'+c['intro']+'</p><div class="toolbar">'+period+channel+'<button id="reset" type="button">필터 초기화</button></div><p id="status" class="live" role="status" aria-live="polite"></p><div id="stats" class="stats"></div>'+body+'<details><summary>이 예시의 범위와 수정 방법</summary><p>'+c['note']+'</p><p>HTML 안에 스타일과 스크립트가 모두 포함되어 있습니다. 외부 설치·네트워크 요청 없이 열립니다. 브라우저에서 바꾼 필터는 저장되지 않습니다. 실제 데이터 연결·로그인·권한·서버 저장 기능은 포함하지 않습니다.</p><p>이 파일과 함께 원하는 지표·데이터 형식·유지할 디자인을 에이전트에 전달하세요. 스크립트의 DATA 배열이 예시 데이터 위치입니다.</p></details></main><footer>제인의 픽 · Jane / Dante Labs · 자체 제작 예시 · MIT<br>다른 서비스의 화면·브랜드·실제 개인정보를 사용하지 않았습니다.</footer><script>'+script+'</script></body></html>\n'
 (ROOT/'templates'/f'{key}.html').write_text(html)
manifest={p.name:hashlib.sha256(p.read_bytes()).hexdigest() for p in sorted((ROOT/'templates').glob('*.html'))}
(ROOT/'manifest.json').write_text(json.dumps({'version':'1.0.0','sha256':manifest},indent=2)+'\n')
print(manifest)
